import doctest
import os
import sys

here = os.path.dirname(__file__)
readme = os.path.join(here, "..", "README.rst")


def additional_tests():
	if sys.maxunicode >= 0x10000:
		return doctest.DocFileSuite("../README.rst")
	else:
		return doctest.DocFileSuite()


def test_readme():
	"""Check that the examples in README.rst produce the documented output."""
	if sys.maxunicode < 0x10000:
		return

	results = doctest.testfile(readme, module_relative=False)
	assert results.failed == 0, "%d of %d README examples failed" % (
			results.failed, results.attempted)
	assert results.attempted > 0, "no examples found in README.rst"


def test_docstrings():
	"""Check that the examples in the unidecode docstrings are correct."""
	import unidecode

	results = doctest.testmod(unidecode)
	assert results.failed == 0, "%d of %d docstring examples failed" % (
			results.failed, results.attempted)
	assert results.attempted > 0, "no examples found in unidecode docstrings"
